func csrfProtectionValidateConfiguredURLList(ctx context.Context, wrapper types.Object) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if wrapper.IsNull() || wrapper.IsUnknown() {
		return diagnostics
	}
	var value csrfProtectionWrapperModel
	diagnostics.Append(wrapper.As(ctx, &value, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() || value.Items.IsNull() || value.Items.IsUnknown() {
		return diagnostics
	}
	if len(value.Items.Elements()) > csrfProtectionURLListMaxItems {
		diagnostics.AddError("Invalid CSRF protection url_list", fmt.Sprintf("url_list may contain at most %d item blocks.", csrfProtectionURLListMaxItems))
		return diagnostics
	}
	var items []csrfProtectionURLListItemModel
	diagnostics.Append(value.Items.ElementsAs(ctx, &items, false)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	for index, item := range items {
		location := fmt.Sprintf("url_list item %d", index+1)
		if !item.Name.IsNull() && !item.Name.IsUnknown() {
			if utf8.RuneCountInString(item.Name.ValueString()) > 63 {
				diagnostics.AddError("Invalid CSRF protection item", fmt.Sprintf("%s name exceeds %d UTF-8 characters.", location, 63))
			}
		}
		if item.URL.IsNull() {
			diagnostics.AddError("Invalid CSRF protection item", location+" url is required.")
		} else if !item.URL.IsUnknown() {
			csrfProtectionValidateString(location, " url", item.URL.ValueString(), 0, 255, &diagnostics)
			csrfProtectionValidatePattern(location, " url", item.URL.ValueString(), csrfProtectionURLListURLPattern, "must begin with /", &diagnostics)
		}
		if !item.Value.IsNull() && !item.Value.IsUnknown() {
			if utf8.RuneCountInString(item.Value.ValueString()) > 255 {
				diagnostics.AddError("Invalid CSRF protection item", fmt.Sprintf("%s value exceeds %d UTF-8 characters.", location, 255))
			}
		}
	}
	return diagnostics
}

