func csrfProtectionPlannedBool(configured, planned types.Bool, name string, defaultValue bool, diagnostics *diag.Diagnostics) (bool, bool) {
	if configured.IsNull() {
		return defaultValue, true
	}
	if configured.IsUnknown() {
		if planned.IsNull() || planned.IsUnknown() {
			diagnostics.AddError("Unknown CSRF protection item", "The configured "+name+" is still unknown during apply.")
			return false, false
		}
		return planned.ValueBool(), true
	}
	return configured.ValueBool(), true
}
func csrfProtectionPlannedRequiredString(configured, planned types.String, name string, diagnostics *diag.Diagnostics) (string, bool) {
	if configured.IsNull() {
		diagnostics.AddError("Invalid CSRF protection item", "The required "+name+" is null.")
		return "", false
	}
	if configured.IsUnknown() {
		if planned.IsNull() || planned.IsUnknown() {
			diagnostics.AddError("Unknown CSRF protection item", "The configured "+name+" is still unknown during apply.")
			return "", false
		}
		return planned.ValueString(), true
	}
	return configured.ValueString(), true
}
func csrfProtectionPlannedOptionalString(configured, planned types.String, name string, maximum int, diagnostics *diag.Diagnostics) *string {
	if configured.IsNull() {
		// Omission preserves the prior state value carried into the plan by
		// use_state_for_unknown; a null planned value (e.g. a clear-string
		// modifier) drops the field so the backend removes it.
		if !planned.IsNull() && !planned.IsUnknown() {
			value := planned.ValueString()
			if maximum > 0 && utf8.RuneCountInString(value) > maximum {
				diagnostics.AddError("Invalid CSRF protection item", fmt.Sprintf("The %s exceeds %d UTF-8 characters.", name, maximum))
			}
			return &value
		}
		return nil
	}
	value := ""
	if configured.IsUnknown() {
		if planned.IsNull() {
			return nil
		}
		if planned.IsUnknown() {
			diagnostics.AddError("Unknown CSRF protection item", "The configured "+name+" is still unknown during apply.")
			return nil
		}
		value = planned.ValueString()
	} else {
		value = configured.ValueString()
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Invalid CSRF protection item", fmt.Sprintf("The %s exceeds %d UTF-8 characters.", name, maximum))
	}
	return &value
}
