func csrfProtectionDecodeOptionalInt64(object map[string]json.RawMessage, key, location string, diagnostics *diag.Diagnostics) int64 {
	raw, ok := object[key]
	if !ok || csrfProtectionJSONNull(raw) {
		return 0
	}
	var number json.Number
	if err := json.Unmarshal(raw, &number); err != nil {
		diagnostics.AddError("Malformed CSRF protection result", location+" "+key+" was not an integer.")
		return 0
	}
	value, err := number.Int64()
	if err != nil {
		diagnostics.AddError("Malformed CSRF protection result", location+" "+key+" was not an integer.")
		return 0
	}
	return value
}

// DecodeOptionalInt64WithDefault decodes an optional integer item field,
// substituting the reviewed default when the successful GET omits the key or
// returns null. This mirrors the encode path (PlannedOptionalInt64 sends the
// reviewed default when the practitioner omits the field), so state carries the
// reviewed default rather than 0 and a later update does not reuse a stale 0.
func csrfProtectionDecodeOptionalInt64WithDefault(object map[string]json.RawMessage, key, location string, defaultValue int64, diagnostics *diag.Diagnostics) int64 {
	raw, ok := object[key]
	if !ok || csrfProtectionJSONNull(raw) {
		return defaultValue
	}
	var number json.Number
	if err := json.Unmarshal(raw, &number); err != nil {
		diagnostics.AddError("Malformed CSRF protection result", location+" "+key+" was not an integer.")
		return 0
	}
	value, err := number.Int64()
	if err != nil {
		diagnostics.AddError("Malformed CSRF protection result", location+" "+key+" was not an integer.")
		return 0
	}
	return value
}

func csrfProtectionDecodeScalars(result client.WAFModuleResult) (csrfProtectionScalars, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	scalarsResult := csrfProtectionScalars{}

	actionRaw, ok := result.Configs["action"]
	if !ok || csrfProtectionJSONNull(actionRaw) {
		diagnostics.AddError("Malformed CSRF protection result", "The successful API result did not contain a non-null action string.")
	} else {
		var actionValue string
		if err := json.Unmarshal(actionRaw, &actionValue); err != nil || !csrfProtectionConfigActionValid(actionValue) {
			diagnostics.AddError("Malformed CSRF protection result", "The successful API result contained an invalid action.")
		} else {
			scalarsResult.Action = actionValue
		}
	}

	statusRaw, ok := result.Configs["status"]
	if !ok || csrfProtectionJSONNull(statusRaw) {
		diagnostics.AddError("Malformed CSRF protection result", "The successful API result did not contain a non-null status boolean.")
	} else {
		var statusValue bool
		if err := json.Unmarshal(statusRaw, &statusValue); err != nil {
			diagnostics.AddError("Malformed CSRF protection result", "The successful API result contained an invalid status.")
		} else {
			scalarsResult.Status = statusValue
		}
	}
	return scalarsResult, diagnostics
}

func csrfProtectionDecodePageList(raw json.RawMessage) (csrfProtectionPageListOwnedList, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(raw) == 0 {
		return csrfProtectionPageListOwnedList{}, diagnostics
	}
	if csrfProtectionJSONNull(raw) {
		diagnostics.AddError("Malformed CSRF protection result", "The successful API result contained null page_list instead of an array.")
		return csrfProtectionPageListOwnedList{}, diagnostics
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed CSRF protection result", "The successful API result contained a non-array page_list value.")
		return csrfProtectionPageListOwnedList{}, diagnostics
	}
	if len(rawItems) > csrfProtectionPageListMaxItems {
		diagnostics.AddError("Malformed CSRF protection result", fmt.Sprintf("The successful API result contained more than %d page_list items.", csrfProtectionPageListMaxItems))
		return csrfProtectionPageListOwnedList{}, diagnostics
	}

	items := make([]csrfProtectionPageListWireItem, 0, len(rawItems))
	seen := make(map[int]struct{}, len(rawItems))
	knownKeys := map[string]struct{}{
		"filter": {},
		"idx":    {},
		"name":   {},
		"url":    {},
		"value":  {},
	}
	for position, rawItem := range rawItems {
		location := fmt.Sprintf("page_list item %d", position+1)
		var object map[string]json.RawMessage
		if err := json.Unmarshal(rawItem, &object); err != nil || object == nil {
			diagnostics.AddError("Malformed CSRF protection result", location+" was not an object.")
			continue
		}
		unknown := make([]string, 0)
		for key := range object {
			if _, ok := knownKeys[key]; !ok {
				unknown = append(unknown, key)
			}
		}
		sort.Strings(unknown)
		if len(unknown) != 0 {
			diagnostics.AddError("Unknown CSRF protection item field", location+" contained unsupported keys: "+strings.Join(unknown, ", ")+".")
			continue
		}
		index, ok := csrfProtectionDecodeIndex(object["idx"], location, "int", &diagnostics)
		if !ok {
			continue
		}
		if _, duplicate := seen[index]; duplicate {
			diagnostics.AddError("Malformed CSRF protection result", fmt.Sprintf("%s used duplicate idx %d.", location, index))
			continue
		}
		seen[index] = struct{}{}
		item := csrfProtectionPageListWireItem{Index: index}
		filterValue, ok := csrfProtectionDecodeRequiredBool(object["filter"], location+" filter", &diagnostics)
		if !ok {
			continue
		}
		item.Filter = filterValue
		csrfProtectionRejectItemNullUnlessNullable(object, "name", true, location, &diagnostics)
		item.Name = csrfProtectionDecodeOptionalString(object, "name", location, 63, &diagnostics)
		urlValue, ok := csrfProtectionDecodeRequiredString(object["url"], location+" url", &diagnostics)
		if !ok {
			continue
		}
		csrfProtectionValidateString(location, " url", urlValue, 0, 255, &diagnostics)
		csrfProtectionValidatePattern(location, " url", urlValue, csrfProtectionPageListURLPattern, "must begin with /", &diagnostics)
		item.URL = urlValue
		csrfProtectionRejectItemNullUnlessNullable(object, "value", true, location, &diagnostics)
		item.Value = csrfProtectionDecodeOptionalString(object, "value", location, 255, &diagnostics)
		items = append(items, item)
	}
	if diagnostics.HasError() {
		return csrfProtectionPageListOwnedList{}, diagnostics
	}
	sort.Slice(items, func(i, j int) bool { return items[i].Index < items[j].Index })
	return csrfProtectionPageListOwnedList{Set: true, Items: items}, diagnostics
}

func csrfProtectionPageListWrapperValue(owned csrfProtectionPageListOwnedList, subItemOwnedMasks map[string][]bool) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if !owned.Set {
		return types.ObjectNull(csrfProtectionPageListWrapperAttributeTypes), diagnostics
	}
	elements := make([]attr.Value, 0, len(owned.Items))
	for _, item := range owned.Items {
		objectValues := map[string]attr.Value{}
		objectValues["filter"] = types.BoolValue(item.Filter)
		nameValue := types.StringNull()
		if item.Name != nil {
			nameValue = types.StringValue(*item.Name)
		}
		objectValues["name"] = nameValue
		objectValues["url"] = types.StringValue(item.URL)
		valueValue := types.StringNull()
		if item.Value != nil {
			valueValue = types.StringValue(*item.Value)
		}
		objectValues["value"] = valueValue
		object, objectDiagnostics := types.ObjectValue(csrfProtectionPageListItemAttributeTypes, objectValues)
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: csrfProtectionPageListItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(csrfProtectionPageListWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}

